<div x-cloak x-show="dateModal" x-transition.opacity class="fixed inset-0 z-50 grid place-items-end bg-slate-950/50 p-0 sm:place-items-center sm:p-4" @keydown.escape.window="dateModal=false">
    <div class="w-full rounded-t-3xl bg-white p-5 shadow-2xl sm:max-w-md sm:rounded-3xl" @click.outside="dateModal=false">
        <div class="flex items-start justify-between gap-4"><div><p class="text-xs font-extrabold uppercase tracking-wide text-orange-600">Check availability</p><h3 class="mt-1 text-xl font-black" x-text="dateModalMode==='checkin'?'Select check-in':'Select check-out'"></h3><p class="mt-1 text-xs text-slate-500">Booked dates cannot be selected.</p></div><button type="button" @click="dateModal=false" class="grid size-9 shrink-0 place-items-center rounded-full bg-slate-100 text-lg font-bold text-slate-600" aria-label="Close date picker">×</button></div>
        <div class="mt-5 flex items-center justify-between rounded-xl bg-slate-50 p-2"><button type="button" @click="previous" :disabled="offset===0" class="grid size-9 place-items-center rounded-lg text-lg font-bold disabled:opacity-30" aria-label="Previous month">‹</button><p class="text-sm font-black" x-text="months[0]?.label"></p><button type="button" @click="next" :disabled="offset>=17" class="grid size-9 place-items-center rounded-lg text-lg font-bold disabled:opacity-30" aria-label="Next month">›</button></div>
        <div class="mt-4 grid grid-cols-7 gap-1 text-center"><template x-for="label in ['S','M','T','W','T','F','S']"><span class="py-1 text-[10px] font-bold text-slate-400" x-text="label"></span></template><template x-for="blank in (months[0]?.offset || 0)"><span></span></template><template x-for="day in (months[0]?.days || [])" :key="'guest-modal-'+day.date"><button type="button" @click="selectDate(day)" :disabled="day.past||day.blocked" class="flex aspect-square min-w-0 items-center justify-center rounded-lg text-xs transition" :class="dayClass(day)" :title="day.blocked?'Booked or unavailable':'Available'" x-text="day.number"></button></template></div>
        <p x-show="selectionError" x-text="selectionError" class="mt-3 rounded-lg bg-red-50 p-3 text-xs font-semibold text-red-700"></p>
        <a x-show="checkIn && checkOut" href="{{ route('register', ['redirect' => request()->getRequestUri()]) }}" class="mt-4 block rounded-xl bg-orange-600 px-5 py-3 text-center text-sm font-black text-white">Create account to continue</a>
    </div>
</div>
